import type { Guide } from "@/lib/content";

type GuideDraft = {
  slug: string;
  title: string;
  description: string;
  overview: string;
  evidence: string;
  experience: string;
  safety: string;
  fit: string;
  nextSteps: string;
  sources: Guide["sources"];
};

function buildGuide(draft: GuideDraft): Guide {
  return {
    slug: draft.slug,
    title: draft.title,
    description: `${draft.description} This guide is educational and does not replace medical advice from a qualified healthcare professional.`,
    reviewedOn: "2026-10-17",
    sections: [
      {
        heading: "What this approach means",
        body: `${draft.overview} Names and schedules can differ between programs, so compare the actual intensity, setting, duration, staffing, and services with the person's assessed needs rather than relying on a label. A licensed clinician can help determine whether this approach belongs in a broader treatment plan and revisit that decision when needs change.`,
      },
      {
        heading: "What the evidence supports",
        body: `${draft.evidence} Evidence can be stronger for some outcomes and populations than for others, and one therapy rarely addresses every medical, psychiatric, social, and practical need across recovery. Ask a provider to explain which guidelines or studies support its approach, which outcomes they apply to, and how progress will be measured over time.`,
      },
      {
        heading: "What treatment may include",
        body: `${draft.experience} A program should explain who delivers each service, how often it occurs, what participation requires, and how the pieces connect to an individualized written plan. It should also describe how medications, behavioral care, primary care, family involvement, and recovery supports are coordinated when they are needed.`,
      },
      {
        heading: "Safety and important limitations",
        body: `${draft.safety} If someone may be in immediate danger, is unresponsive, has trouble breathing, has a seizure, or may harm themselves or another person, call 911 rather than waiting for a routine appointment or online reply. Treatment recommendations should change promptly when new safety, withdrawal, medication, medical, or mental health concerns appear.`,
      },
      {
        heading: "How to evaluate fit",
        body: `${draft.fit} Ask who completed the assessment, what credentials the clinicians hold, how progress is reviewed, and what would lead the team to increase, reduce, or change the level of care. Confirm that the program can address co-occurring conditions, respect informed preferences, and arrange a timely transfer when a need falls outside its scope.`,
      },
      {
        heading: "Planning the next steps",
        body: `${draft.nextSteps} Confirm licensing, costs, insurance status, privacy practices, transportation needs, and follow-up arrangements directly with the program and health plan before admission. Keep written estimates, medication instructions, emergency contacts, and scheduled follow-up appointments so the transition remains organized and does not depend on memory alone.`,
      },
    ],
    sources: draft.sources,
  };
}

